function startStop(fuel: number[], cost: number[]): number {
  const n = fuel.length;
  for (let s = 0; s < n; s++) {
    let tank = 0, ok = true;
    for (let k = 0; k < n; k++) {
      const i = (s + k) % n;
      tank += fuel[i] - cost[i];
      if (tank < 0) { ok = false; break; }
    }
    if (ok) return s;
  }
  return -1;
}

