function startStop(fuel: number[], cost: number[]): number {
  let total = 0, tank = 0, start = 0;
  for (let i = 0; i < fuel.length; i++) {
    const gain = fuel[i] - cost[i];
    total += gain;
    tank += gain;
    if (tank < 0) {
      start = i + 1;
      tank = 0;
    }
  }
  return total < 0 ? -1 : start;
}

